1582:       up.connect(new Downstream<T>() {
1583:         @Override
1584:         public void success(T value) {
1585:           try {
1586:             listener.execute(Result.success(value));
1587:           } catch (Exception e) {
1588:             down.error(e);
1589:             return;
1590:           }
1591:           down.success(value);
1592:         }
