1059:    *         Promise.value("foo")
1060:    *           .to(RxRatpack::observe)
1061:    *           .doOnNext(i -> LOG.add("doOnNext"))
1062:    *           .subscribe(LOG::add)
1063:    *     );
1064:    *
1065:    *     assertEquals(Arrays.asList("doOnNext", "foo"), LOG);
1066:    *   }
1067:    * }
1068:    * }</pre>
1069:    * <p>
1070:    * The given function is executed immediately.
1071:    * <p>
1072:    * This method should only be used when converting a promise to another type.
1073:    * See {@link #apply(Function)} for applying custom promise operators.
1074:    *
1075:    * @param function the promise conversion function
1076:    * @param <O> the type the promise will be converted to
1077:    * @return the output of the given function
1078:    * @throws Exception any thrown by the given function
1079:    */
1080:   default <O> O to(Function<? super Promise<T>, ? extends O> function) throws Exception {
1081:     return function.apply(this);
