29: public class DefaultCrypto implements Crypto {
30: 
31:   private final SecretKeySpec secretKeySpec;
32:   private final String algorithm;
33:   private final boolean isInitializationVectorRequired;
34: 
35:   public DefaultCrypto(byte[] key, String algorithm) {
36:     String[] parts = algorithm.split("/");
37:     this.secretKeySpec = new SecretKeySpec(key, parts[0]);
38:     this.algorithm = algorithm;
39:     this.isInitializationVectorRequired = parts.length > 1 && !parts[1].equalsIgnoreCase("ECB");
40:   }
41: 
42:   @Override
43:   public byte[] encrypt(ByteBuf message) {
44:     return Exceptions.uncheck(() -> {
45:       Cipher cipher = Cipher.getInstance(algorithm);
46:       cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);
47: 
48:       int blockSize = cipher.getBlockSize();
49:       int messageLength = message.readableBytes();
50:       int encMessageLength = cipher.getOutputSize(messageLength);
51: 
52:       ByteBuf paddedMessage = null;
53:       if (messageLength == encMessageLength && (encMessageLength % blockSize) != 0) {
54:         int paddedMessageSize = messageLength + blockSize - (messageLength % blockSize);
55:         paddedMessage = Unpooled.wrappedBuffer(new byte[paddedMessageSize]);
56:         paddedMessage.setZero(0, paddedMessageSize);
57:         paddedMessage.setBytes(0, message, messageLength);
58:         encMessageLength = cipher.getOutputSize(paddedMessageSize);
59:       }
60: 
61:       ByteBuf encMessage = Unpooled.wrappedBuffer(new byte[encMessageLength]);
62: 
63:       ByteBuffer nioMessageBuf = paddedMessage != null ? paddedMessage.nioBuffer() : message.nioBuffer();
64:       ByteBuffer nioEncMessageBuf = encMessage.nioBuffer();
65: 
66:       cipher.doFinal(nioMessageBuf, nioEncMessageBuf);
67:       byte[] payload = encMessage.array();
68: 
69:       if (paddedMessage != null) {
70:         paddedMessage.release();
71:       }
72:       encMessage.release();
73: 
74:       if (isInitializationVectorRequired) {
75:         byte[] ivBytes = cipher.getIV();
76: 
77:         int outputLength = 1 + ivBytes.length + payload.length;
78:         ByteBuf output = Unpooled.wrappedBuffer(new byte[outputLength])
79:           .resetWriterIndex()
80:           .writeByte(ivBytes.length)
81:           .writeBytes(ivBytes)
82:           .writeBytes(payload);
83: 
84:         payload = output.array();
85: 
86:         output.release();
87:       }
88: 
89:       return payload;
90:     });
91:   }
92: 
93:   @Override
94:   public byte[] decrypt(ByteBuf message) {
95:     return Exceptions.uncheck(() -> {
96:       Cipher cipher = Cipher.getInstance(algorithm);
97: 
98:       if (isInitializationVectorRequired) {
99:         int ivByteLength = message.readByte();
100:         ByteBuf ivBytes = message.readBytes(ivByteLength);
101:         IvParameterSpec ivParameterSpec = new IvParameterSpec(ivBytes.array());
102:         ivBytes.release();
103: 
104:         cipher.init(Cipher.DECRYPT_MODE, secretKeySpec, ivParameterSpec);
105:       } else {
106:         cipher.init(Cipher.DECRYPT_MODE, secretKeySpec);
107:       }
108: 
109:       int messageLength = message.readableBytes();
110:       ByteBuf decMessage = Unpooled.wrappedBuffer(new byte[cipher.getOutputSize(messageLength)]);
111: 
112:       ByteBuffer nioMessageBuf = message.readBytes(messageLength).nioBuffer();
113:       ByteBuffer nioDecMessageBuf = decMessage.nioBuffer();
114: 
115:       int count = cipher.doFinal(nioMessageBuf, nioDecMessageBuf);
116:       for (int i = count - 1; i >= 0; i--) {
117:         if (nioDecMessageBuf.get(i) == 0x00) {
118:           count--;
119:         }
120:       }
121:       byte[] decrypted = new byte[count];
122:       nioDecMessageBuf.position(0);
123:       nioDecMessageBuf.get(decrypted, 0, count);
124: 
125:       decMessage.release();
126: 
127:       return decrypted;
128:     });
129:   }
