377:   public void error(Throwable throwable) {
378:     ServerErrorHandler serverErrorHandler = get(ServerErrorHandler.class);
379:     throwable = unpackThrowable(throwable);
380: 
381:     ThrowableHolder throwableHolder = getRequest().maybeGet(ThrowableHolder.class).orElse(null);
382:     if (throwableHolder == null) {
383:       getRequest().add(ThrowableHolder.class, new ThrowableHolder(throwable));
384: 
385:       try {
386:         serverErrorHandler.error(this, throwable);
387:       } catch (Throwable errorHandlerThrowable) {
388:         onErrorHandlerError(serverErrorHandler, throwable, errorHandlerThrowable);
389:       }
390:     } else {
391:       onErrorHandlerError(serverErrorHandler, throwableHolder.getThrowable(), throwable);
392:     }
393:   }
394: 
395:   private void onErrorHandlerError(ServerErrorHandler serverErrorHandler, Throwable original, Throwable errorHandlerThrowable) {
396:     String msg = "Throwable thrown by error handler " + serverErrorHandler + " while handling throwable\n"
397:       + "Original throwable: " + getStackTraceAsString(original) + "\n"
398:       + "Error handler throwable: " + getStackTraceAsString(errorHandlerThrowable);
399: 
400:     LOGGER.error(msg);
401: 
402:     Response response = requestConstants.response.status(500);
403:     if (getServerConfig().isDevelopment()) {
404:       response.send(msg);
405:     } else {
406:       response.send();
407:     }
408:   }
409: 
410:   private Throwable unpackThrowable(Throwable throwable) {
411:     if (throwable instanceof UndeclaredThrowableException) {
412:       return throwable.getCause();
413:     } else {
414:       return throwable;
415:     }
416:   }
