+    this.object = object;
+    this.handlers = handlers;
+  }
+
+  @SuppressWarnings("unchecked")
+  public void handle(Context context) {
+    if (type == null) {
+      context.insert(object, handlers);
+    } else {
+      context.insert((Class)type, object, handlers);
+    }
+  }
+}

