113:   private boolean isBytesAreSame() throws IOException {
114:     lock.lock();
115:     try {
116:       ByteBuf existing = contentHolder.get();
117:       //noinspection SimplifiableIfStatement
118:       if (existing == null) {
119:         return false;
120:       }
121: 
122:       return IoUtils.read(UnpooledByteBufAllocator.DEFAULT, file).equals(existing);
123:     } finally {
124:       lock.unlock();
125:     }
126:   }
127: 
128:   private boolean refreshNeeded() throws IOException {
129:     return !Files.getLastModifiedTime(file).equals(lastModifiedHolder.get()) || !isBytesAreSame();
130:   }
131: 
132:   private void refresh() throws Exception {
133:     lock.lock();
134:     try {
135:       FileTime lastModifiedTime = Files.getLastModifiedTime(file);
136:       ByteBuf content = IoUtils.read(UnpooledByteBufAllocator.DEFAULT, file);
137: 
138:       if (lastModifiedTime.equals(lastModifiedHolder.get()) && content.equals(contentHolder.get())) {
139:         return;
140:       }
141: 
142:       T previous = delegateHolder.getAndSet(null);
143:       if (previous != null) {
144:         releaser.release(previous);
145:       }
146:       delegateHolder.set(producer.produce(file, content));
147: 
148:       this.lastModifiedHolder.set(lastModifiedTime);
149:       this.contentHolder.set(content);
150:     } finally {
151:       lock.unlock();
152:     }
153:   }
