33: public class CachingPromise<T> implements Promise<T> {
34: 
35:   private final Action<? super Fulfiller<T>> fulfillment;
36:   private final Supplier<ExecutionBacking> executionSupplier;
37:   private final Action<? super Throwable> errorHandler;
38: 
39:   private final AtomicBoolean fired = new AtomicBoolean();
40: 
41:   private final ConcurrentLinkedQueue<Fulfiller<T>> waiting = new ConcurrentLinkedQueue<>();
42:   private final AtomicBoolean draining = new AtomicBoolean();
43:   private final AtomicReference<Result<T>> result = new AtomicReference<>();
44: 
45:   public CachingPromise(Action<? super Fulfiller<T>> action, Supplier<ExecutionBacking> executionSupplier, Action<? super Throwable> errorHandler) {
46:     this.fulfillment = action;
47:     this.executionSupplier = executionSupplier;
48:     this.errorHandler = errorHandler;
49:   }
50: 
51:   @Override
52:   public SuccessPromise<T> onError(Action<? super Throwable> errorHandler) {
53:     return new DefaultSuccessPromise<>(executionSupplier, new Fulfillment(), errorHandler);
54:   }
55: 
56:   @Override
57:   public void then(Action<? super T> then) {
58:     newPromise().then(then);
59:   }
60: 
61:   private void tryDrain() {
62:     if (draining.compareAndSet(false, true)) {
63:       try {
64:         Result<T> result = this.result.get();
65: 
66:         Fulfiller<T> poll = waiting.poll();
67:         while (poll != null) {
68:           fulfill(result, poll);
69:           poll = waiting.poll();
70:         }
71:       } finally {
72:         draining.set(false);
73:       }
74:     }
75:     if (!waiting.isEmpty()) {
76:       tryDrain();
77:     }
78:   }
79: 
80:   private DefaultSuccessPromise<T> newPromise() {
81:     return new DefaultSuccessPromise<>(executionSupplier, new Fulfillment(), errorHandler);
82:   }
83: 
84:   @Override
85:   public <O> Promise<O> map(Function<? super T, ? extends O> transformer) {
86:     return newPromise().map(transformer);
87:   }
88: 
89:   @Override
90:   public <O> Promise<O> blockingMap(Function<? super T, ? extends O> transformer) {
91:     return newPromise().blockingMap(transformer);
92:   }
93: 
94:   @Override
95:   public <O> Promise<O> flatMap(Function<? super T, ? extends Promise<O>> transformer) {
96:     return newPromise().flatMap(transformer);
97:   }
98: 
99:   @Override
100:   public Promise<T> route(Predicate<? super T> predicate, Action<? super T> action) {
101:     return newPromise().route(predicate, action);
102:   }
103: 
104:   @Override
105:   public Promise<T> onNull(NoArgAction action) {
106:     return newPromise().onNull(action);
107:   }
108: 
109:   @Override
110:   public Promise<T> cache() {
111:     return this;
112:   }
