36: public class DefaultHttpUrlBuilder implements HttpUrlBuilder {
37: 
38:   private static final CharMatcher HOST_NAME_ILLEGAL_CHARS = CharMatcher.inRange('a', 'z')
39:     .or(CharMatcher.inRange('A', 'Z'))
40:     .or(CharMatcher.inRange('0', '9'))
41:     .or(CharMatcher.anyOf(".-"))
42:     .negate()
43:     .precomputed();
44: 
45:   private static final Joiner PATH_JOINER = Joiner.on("/");
46: 
47:   private String protocol = "http";
48:   private String host = "localhost";
49:   private int port = -1;
50:   private final List<String> pathSegments = new LinkedList<>();
51:   private final Multimap<String, Object> params = MultimapBuilder.linkedHashKeys().linkedListValues().build();
52:   private boolean hasTrailingSlash;
53: 
54:   public DefaultHttpUrlBuilder() {
55:   }
56: 
57:   public DefaultHttpUrlBuilder(URI uri) {
58:     this.pathSegments.clear(); //TODO Review I think this is correct or mabye add a reset / clear
59:     this.protocol = uri.getScheme();
60:     if (protocol == null) {
61:       protocol = "http";
62:     }
63: 
64:     protocol = protocol.toLowerCase();
65:     if (!protocol.equals("http") && !protocol.equals("https")) {
66:       throw new IllegalArgumentException("uri " + uri + " must be a http or https uri");
67:     }
68: 
69:     host(uri.getHost());
70:     port(uri.getPort());
71:     String rawPath = uri.getRawPath();
72:     if (rawPath != null && !rawPath.isEmpty() && !rawPath.equals("/")) {
73:       String[] parts = rawPath.substring(1).split("/");
74:       for (String part : parts) {
75:         try {
76:           // have to encode + to stop URLDecoder from treating it as a space (it's only synonymous with %20 in query strings)
77:           String s = part.replaceAll("\\+", "%2B");
78:           segment(URLDecoder.decode(s, "UTF8"));
79:         } catch (UnsupportedEncodingException e) {
80:           throw new InternalRatpackError("UTF8 is not available", e);
81:         }
82:       }
83:       hasTrailingSlash = rawPath.substring(rawPath.length() - 1, rawPath.length()).equals("/");
84:     }
85: 
86:     if (uri.getRawQuery() != null) {
87:       Map<String, List<String>> parameters = new QueryStringDecoder(uri).parameters();
88:       for (Map.Entry<String, List<String>> entry : parameters.entrySet()) {
89:         if (entry.getKey() != null) {
90:           params.putAll(entry.getKey(), entry.getValue());
91:         }
92:       }
93:     }
94:   }
95: 
96:   @Override
97:   public HttpUrlBuilder secure() {
98:     this.protocol = "https";
99:     return this;
100:   }
101: 
102:   @Override
103:   public HttpUrlBuilder host(String host) {
104:     // http://en.wikipedia.org/wiki/Hostname#Restrictions%5Fon%5Fvalid%5Fhost%5Fnames
105:     int indexIn = HOST_NAME_ILLEGAL_CHARS.indexIn(host);
106:     if (indexIn >= 0) {
107:       throw new IllegalArgumentException("character '" + host.charAt(indexIn) + "' of host name '" + host + "' is invalid (only [a-zA-Z0-9.-] are allowed in host names)");
108:     }
109:     this.host = host;
110:     return this;
111:   }
112: 
113:   @Override
114:   public HttpUrlBuilder port(int port) {
115:     if (port == 0 || port < -1) {
116:       throw new IllegalArgumentException("port must be greater than 0 or exactly -1, is " + port);
117:     }
118:     this.port = port;
119:     return this;
120:   }
121: 
122:   @Override
123:   public HttpUrlBuilder path(String path) {
124:     Objects.requireNonNull(path, "path must not be null");
125:     Collections.addAll(pathSegments, path.split("/"));
126:     return this;
127:   }
128: 
129:   @Override
130:   public HttpUrlBuilder segment(String segment) {
131:     Objects.requireNonNull(segment, "pathSegment must not be null");
132:     pathSegments.add(segment);
133:     return this;
134:   }
135: 
136:   @Override
137:   public HttpUrlBuilder params(String... params) {
138:     int i = 0;
139:     while (i < params.length) {
140:       String key = params[i];
141:       String value = "";
142:       if (++i < params.length) {
143:         value = params[i++];
144:       }
145: 
146:       this.params.put(key, value);
147:     }
148: 
149:     return this;
150:   }
151: 
152:   @Override
153:   public HttpUrlBuilder params(Map<String, ?> params) {
154:     for (Map.Entry<String, ?> entry : params.entrySet()) {
155:       this.params.put(entry.getKey(), entry.getValue());
156:     }
157: 
158:     return this;
159:   }
160: 
161:   @Override
162:   public HttpUrlBuilder params(Multimap<String, ?> params) {
163:     this.params.putAll(params);
164:     return this;
165:   }
166: 
167:   @Override
168:   public HttpUrlBuilder params(MultiValueMap<String, ?> params) {
169:     for (String s : params.keySet()) {
170:       this.params.putAll(s, params.getAll(s));
171:     }
172:     return this;
173:   }
174: 
175:   public URI build() {
176:     String string = toString();
177: 
178:     try {
179:       return new URI(string);
180:     } catch (URISyntaxException e) {
181:       throw new InternalRatpackError("HttpUriBuilder produced invalid URI: " + toString(), e);
182:     }
183:   }
184: 
185:   private void appendPathString(StringBuilder stringBuilder) {
186:     if (!pathSegments.isEmpty()) {
187:       stringBuilder.append("/");
188:       PATH_JOINER.appendTo(stringBuilder, Iterables.transform(pathSegments, input -> UrlEscapers.urlPathSegmentEscaper().escape(input)));
189:     }
190:   }
191: 
192:   private void appendQueryString(StringBuilder stringBuilder) {
193:     if (!params.isEmpty()) {
194:       stringBuilder.append("?");
195:       Iterator<Map.Entry<String, Object>> parts = params.entries().iterator();
196:       if (parts.hasNext()) {
197:         Map.Entry<String, Object> entry = parts.next();
198:         stringBuilder.append(UrlEscapers.urlFormParameterEscaper().escape(entry.getKey()));
199:         String value = entry.getValue().toString();
200:         if (value != null && value.length() > 0) {
201:           stringBuilder.append("=");
202:           stringBuilder.append(UrlEscapers.urlFormParameterEscaper().escape(value));
203:         }
204:         while (parts.hasNext()) {
205:           stringBuilder.append("&");
206:           Map.Entry<String, Object> e = parts.next();
207:           stringBuilder.append(UrlEscapers.urlFormParameterEscaper().escape(e.getKey()));
208:           String v = e.getValue().toString();
209:           if (v != null && v.length() > 0) {
210:             stringBuilder.append("=");
211:             stringBuilder.append(UrlEscapers.urlFormParameterEscaper().escape(v));
212:           }
213:         }
214:       }
215:     }
216:   }
217: 
218: 
219:   @Override
220:   public String toString() {
221:     StringBuilder uri = new StringBuilder(protocol).append("://").append(host);
222:     if (port > -1) {
223:       uri.append(":").append(port);
224:     }
225:     appendPathString(uri);
226:     if (hasTrailingSlash) {
227:       uri.append("/");
228:     }
229:     appendQueryString(uri);
230: 
231:     return uri.toString();
232:   }
233: }
