28: public class BufferingPublisher<T> implements TransformablePublisher<T> {
29: 
30:   private final Publisher<? extends T> disposer;
31: 
32:   public BufferingPublisher(Publisher<? extends T> publisher) {
33:     this.disposer = publisher;
34:   }
35: 
36:   @Override
37:   public void subscribe(final Subscriber<? super T> subscriber) {
38:     new Subscription(subscriber);
39:   }
40: 
41:   private class Subscription extends SubscriptionSupport<T> {
42: 
43:     // if null, using passthru
44:     private BufferingSubscriber bufferingSubscriber;
45: 
46:     private final AtomicBoolean upstreamFinished;
47: 
48:     private final AtomicReference<org.reactivestreams.Subscription> upstreamSubscription;
49:     private final AtomicBoolean requestedUpstream;
50: 
51:     public Subscription(Subscriber<? super T> subscriber) {
52:       super(subscriber);
53:       upstreamFinished = new AtomicBoolean();
54:       upstreamSubscription = new AtomicReference<>();
55:       requestedUpstream = new AtomicBoolean();
56:       start();
57:     }
58: 
59:     protected void doRequest(long n) {
60:       if (!isStopped()) {
61:         if (requestedUpstream.compareAndSet(false, true)) {
62:           if (n == Long.MAX_VALUE) {
63:             disposer.subscribe(new PassThruSubscriber());
64:           } else {
65:             bufferingSubscriber = new BufferingSubscriber();
66:             disposer.subscribe(bufferingSubscriber);
67:             bufferingSubscriber.wanted.addAndGet(n);
68:             bufferingSubscriber.tryDrain();
69:           }
70:         } else {
71:           if (bufferingSubscriber != null && !bufferingSubscriber.open.get()) {
72:             if (bufferingSubscriber.wanted.addAndGet(n) >= 0) {
73:               bufferingSubscriber.open.set(true);
74:             }
75:             bufferingSubscriber.tryDrain();
76:           }
77:         }
78:       }
79:     }
80: 
81:     @Override
82:     protected void doCancel() {
83:       org.reactivestreams.Subscription subscription = upstreamSubscription.getAndSet(null);
84:       if (subscription != null) {
85:         subscription.cancel();
86:       }
87:       if (bufferingSubscriber != null) {
88:         bufferingSubscriber.wanted.set(Long.MIN_VALUE);
89:         bufferingSubscriber = null;
90:       }
91:     }
92: 
93:     class PassThruSubscriber implements Subscriber<T> {
94:       @Override
95:       public void onSubscribe(org.reactivestreams.Subscription s) {
96:         upstreamSubscription.set(s);
97:         s.request(Long.MAX_VALUE);
98:       }
99: 
100:       @Override
101:       public void onNext(T t) {
102:         Subscription.this.onNext(t);
103:       }
104: 
105:       @Override
106:       public void onError(Throwable t) {
107:         Subscription.this.onError(t);
108:       }
109: 
110:       @Override
111:       public void onComplete() {
112:         Subscription.this.onComplete();
113:       }
114:     }
115: 
116:     class BufferingSubscriber implements Subscriber<T> {
117:       private final AtomicLong wanted = new AtomicLong(Long.MIN_VALUE);
118:       private final AtomicBoolean open = new AtomicBoolean();
119:       private final ConcurrentLinkedQueue<T> buffer = new ConcurrentLinkedQueue<>();
120:       private final AtomicBoolean draining = new AtomicBoolean();
121: 
122:       @Override
123:       public void onSubscribe(org.reactivestreams.Subscription s) {
124:         if (isStopped()) {
125:           s.cancel();
126:         }
127:         upstreamSubscription.set(s);
128:         s.request(Long.MAX_VALUE);
129:       }
130: 
131:       @Override
132:       public void onNext(T t) {
133:         buffer.add(t);
134:         tryDrain();
135:       }
136: 
137:       @Override
138:       public void onError(Throwable t) {
139:         buffer.clear();
140:         upstreamFinished.set(true);
141:         Subscription.this.onError(t);
142:       }
143: 
144:       @Override
145:       public void onComplete() {
146:         upstreamFinished.set(true);
147:         tryDrain();
148:       }
149: 
150:       public void tryDrain() {
151:         if (draining.compareAndSet(false, true)) {
152:           try {
153:             long i = wanted.get();
154:             while (open.get() || i > Long.MIN_VALUE) {
155:               T item = buffer.poll();
156:               if (item == null) {
157:                 if (upstreamFinished.get()) {
158:                   Subscription.this.onComplete();
159:                   return;
160:                 } else {
161:                   break;
162:                 }
163:               } else {
164:                 Subscription.this.onNext(item);
165:                 i = wanted.decrementAndGet();
166:               }
167:             }
168:           } finally {
169:             draining.set(false);
170:           }
171:           if (buffer.peek() != null && wanted.get() > Long.MIN_VALUE) {
172:             tryDrain();
173:           }
174:         }
175:       }
176: 
177:     }
178:   }
179: }
