262:   /**
263:    * Adds a handler that serves files from the file system.
264:    * <p>
265:    * The given action configures how and what files will be served.
266:    * The handler binds to a {@link FileHandlerSpec#path(String) request path}
267:    * and a {@link FileHandlerSpec#dir(String) directory} within the current filesystem binding.
268:    * The portion of the request path <i>past</i> the path binding identifies the target file within the directory.
269:    *
270:    * <pre class="java">{@code
271:    * import ratpack.test.embed.EphemeralBaseDir;
272:    * import ratpack.test.embed.EmbeddedApp;
273:    *
274:    * import static org.junit.Assert.assertEquals;
275:    *
276:    * public class Example {
277:    *   public static void main(String... args) throws Exception {
278:    *     EphemeralBaseDir.tmpDir().use(baseDir -> {
279:    *       baseDir.write("public/some.text", "foo");
280:    *       baseDir.write("public/index.html", "bar");
281:    *       EmbeddedApp.of(s -> s
282:    *         .serverConfig(c -> c.baseDir(baseDir.getRoot()))
283:    *         .handlers(c -> c
284:    *           .files(f -> f.dir("public").indexFiles("index.html"))
285:    *         )
286:    *       ).test(httpClient -> {
287:    *         assertEquals("foo", httpClient.getText("some.text"));
288:    *         assertEquals("bar", httpClient.getText());
289:    *         assertEquals(404, httpClient.get("no-file-here").getStatusCode());
290:    *       });
291:    *     });
292:    *   }
293:    * }
294:    * }</pre>
295:    *
296:    * @param config the file handler configuration
297:    * @return {@code this}
298:    * @throws Exception any thrown by {@code config}
299:    * @see Handlers#files(ServerConfig, Action)
300:    * @see FileHandlerSpec
301:    */
302:   default Chain files(Action<? super FileHandlerSpec> config) throws Exception {
303:     return all(Handlers.files(getServerConfig(), config));
304:   }
