217:   public void next() {
218:     Handler handler = null;
219: 
220:     ChainIndex index = requestConstants.indexes.peek();
221:     while (handler == null) {
222:       if (index.hasNext()) {
223:         handler = index.next();
224:         if (handler.getClass().equals(ChainHandler.class)) {
225:           requestConstants.indexes.push(new ChainIndex(((ChainHandler) handler).getHandlers(), getRegistry(), false));
226:           index = requestConstants.indexes.peek();
227:           handler = null;
228:         }
229:       } else if (index.first) {
230:         handler = requestConstants.applicationConstants.end;
231:       } else {
232:         requestConstants.indexes.pop();
233:         index = requestConstants.indexes.peek();
234:       }
235:     }
236: 
237:     try {
238:       requestConstants.handler = handler;
239:       handler.handle(this);
240:     } catch (Throwable e) {
241:       if (e instanceof HandlerException) {
242:         throw (HandlerException) e;
243:       } else {
244:         throw new HandlerException(e);
245:       }
246:     }
247:   }
