355:   public void lastModified(Date date, Runnable runnable) {
356:     Date ifModifiedSinceHeader = requestConstants.request.getHeaders().getDate(IF_MODIFIED_SINCE);
357:     long lastModifiedSecs = date.getTime() / 1000;
358: 
359:     if (ifModifiedSinceHeader != null) {
360:       long time = ifModifiedSinceHeader.getTime();
361:       long ifModifiedSinceSecs = time / 1000;
362: 
363:       if (lastModifiedSecs == ifModifiedSinceSecs) {
364:         requestConstants.response.status(NOT_MODIFIED.code()).send();
365:         return;
366:       }
367:     }
368: 
369:     requestConstants.response.getHeaders().setDate(HttpHeaderConstants.LAST_MODIFIED, date);
370:     runnable.run();
371:   }
