17: package org.ratpackframework.session.internal;
18: 
19: import org.ratpackframework.session.Session;
20: import org.ratpackframework.session.SessionConfig;
21: import org.ratpackframework.util.HttpDateUtil;
22: import org.vertx.java.core.http.HttpServerRequest;
23: 
24: import java.util.Calendar;
25: import java.util.Date;
26: import java.util.TimeZone;
27: 
28: public class RequestSessionManager {
29: 
30:   private static final String COOKIE_NAME = "JSESSIONID";
31: 
32:   private final HttpServerRequest exchange;
33:   private final SessionConfig sessionConfig;
34: 
35:   private String cookieSessionId;
36:   private String assignedCookieId;
37:   private boolean alreadySetCookie;
38: 
39:   public RequestSessionManager(HttpServerRequest request, SessionConfig sessionConfig) {
40:     this.exchange = request;
41:     this.sessionConfig = sessionConfig;
42:   }
43: 
44:   private String getCookieSessionId() {
45:     if (cookieSessionId == null) {
46:       String cookieHeader = exchange.headers().get("cookie");
47:       if (cookieHeader != null) {
48:         CookieTokenizer tokenizer = new CookieTokenizer();
49:         int num = tokenizer.tokenize(cookieHeader);
50:         for (int i = 0; i < num; i += 2) {
51:           String token = tokenizer.tokenAt(i);
52:           if (token.equals(COOKIE_NAME) && i < (num - 1)) {
53:             cookieSessionId = tokenizer.tokenAt(i + 1);
54:             break;
55:           }
56:         }
57:       }
58:     }
59: 
60:     return cookieSessionId;
61:   }
62: 
63:   public Session getSession() {
64:     return new Session() {
65:       @Override
66:       public String getId() {
67:         return getSessionIdOrInit();
68:       }
69: 
70:       @Override
71:       public String getExistingId() {
72:         return getCookieSessionId();
73:       }
74: 
75:       @Override
76:       public String regen() {
77:         String existingId = getExistingId();
78:         if (existingId != null) {
79:           sessionConfig.getSessionListener().sessionTerminated(existingId);
80:         }
81:         return assignId();
82: 
83:       }
84: 
85:       @Override
86:       public void terminate() {
87:         String existingId = getExistingId();
88:         if (existingId == null) {
89:           throw new IllegalStateException("Cannot terminate inactive session");
90:         }
91:         sessionConfig.getSessionListener().sessionTerminated(existingId);
92:         setCookie("", new Date(0));
93:       }
94:     };
95:   }
96: 
97:   private String getSessionIdOrInit() {
98:     if (assignedCookieId != null) {
99:       return assignedCookieId;
100:     }
101: 
102:     String cookieSessionId = getCookieSessionId();
103:     if (cookieSessionId != null) {
104:       return cookieSessionId;
105:     }
106: 
107:     assignedCookieId = assignId();
108:     return assignedCookieId;
109:   }
110: 
111:   private String assignId() {
112:     String id = sessionConfig.getIdGenerator().generateSessionId(exchange);
113:     int expiryMins = sessionConfig.getCookieExpiryMins();
114:     if (expiryMins > 0) {
115:       Calendar expires = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
116:       expires.add(Calendar.MINUTE, expiryMins);
117:       setCookie(id, expires.getTime());
118:     } else {
119:       setCookie(id, null);
120:     }
121: 
122:     sessionConfig.getSessionListener().sessionInitiated(id);
123:     return id;
124:   }
125: 
126:   private void setCookie(String value, Date expires) {
127:     if (alreadySetCookie) {
128:       throw new IllegalStateException("Cannot set cookie twice for the one request");
129:     }
130:     alreadySetCookie = true;
131:     StringBuilder setCookieValue = new StringBuilder(COOKIE_NAME).append("=").append(value)
132:         .append(";").append("path=").append(sessionConfig.getCookiePath());
133: 
134:     String cookieDomain = sessionConfig.getCookieDomain();
135:     if (!cookieDomain.equals("localhost")) {
136:       setCookieValue.append(";domain=.").append(cookieDomain);
137:     }
138: 
139:     if (expires != null) {
140:       String expiresString = HttpDateUtil.formatDate(expires, "EEE, dd-MMM-yyyy HH:mm:ss zzz");
141:       setCookieValue.append(";").append("expires=").append(expiresString);
142:     }
143: 
144:     exchange.response.putHeader("Set-Cookie", setCookieValue.toString());
145:   }
146: 
147: }
