39: public class DefaultExecController implements ExecController {
40: 
41:   private static final ThreadLocal<ExecController> THREAD_BINDING = new ThreadLocal<>();
42: 
43:   private final ThreadLocal<Execution> executionHolder = new ThreadLocal<>();
44: 
45:   private final ListeningScheduledExecutorService computeExecutor;
46:   private final ListeningExecutorService blockingExecutor;
47:   private final EventLoopGroup eventLoopGroup;
48:   private final ExecControl control;
49:   private final int numThreads;
50: 
51:   public DefaultExecController(int numThreads) {
52:     this.numThreads = numThreads;
53:     this.eventLoopGroup = new NioEventLoopGroup(numThreads, new ExecControllerBindingThreadFactory("ratpack-compute", Thread.MAX_PRIORITY));
54:     this.computeExecutor = MoreExecutors.listeningDecorator(eventLoopGroup);
55:     this.blockingExecutor = MoreExecutors.listeningDecorator(Executors.newCachedThreadPool(new ExecControllerBindingThreadFactory("ratpack-blocking", Thread.NORM_PRIORITY)));
56:     this.control = new FactoryBackedExecControl();
57:   }
58: 
59:   public static Optional<ExecController> getThreadBoundController() {
60:     return Optional.fromNullable(THREAD_BINDING.get());
61:   }
62: 
63:   public void close() {
64:     eventLoopGroup.shutdownGracefully(0, 0, TimeUnit.SECONDS);
65:     blockingExecutor.shutdown();
66:   }
67: 
68:   @Override
69:   public Execution getExecution() throws ExecutionException {
70:     Execution execution = executionHolder.get();
71:     if (execution == null) {
72:       throw new ExecutionException("No execution is bound to the current thread (are you calling this from a blocking operation or a manual created thread?)");
73:     } else {
74:       return execution;
75:     }
76:   }
77: 
78:   @Override
79:   public ListeningScheduledExecutorService getExecutor() {
80:     return computeExecutor;
81:   }
82: 
83:   @Override
84:   public EventLoopGroup getEventLoopGroup() {
85:     return eventLoopGroup;
86:   }
87: 
88:   @Override
89:   public void start(final Action<? super ratpack.exec.Execution> action) {
90:     if (!isManagedThread() || executionHolder.get() != null) {
91:       computeExecutor.submit(new Runnable() {
92:         @Override
93:         public void run() {
94:           start(action);
95:         }
96:       });
97:     } else {
98:       new Execution(action);
99:     }
100:   }
101: 
102:   private class FactoryBackedExecControl implements ExecControl {
103: 
104:     private final Factory<Execution> executionFactory = new Factory<Execution>() {
105:       @Override
106:       public Execution create() {
107:         return getExecution();
108:       }
109:     };
110: 
111:     @Override
112:     public <T> Promise<T> blocking(final Callable<T> blockingOperation) {
113:       return promise(new Action<Fulfiller<? super T>>() {
114:         @Override
115:         public void execute(final Fulfiller<? super T> fulfiller) throws Exception {
116:           final Execution execution = getExecution();
117:           ListenableFuture<T> future = blockingExecutor.submit(new BlockingOperation(execution));
118:           Futures.addCallback(future, new ComputeResume(fulfiller), computeExecutor);
119:         }
120: 
121:         class BlockingOperation implements Callable<T> {
122:           private final Execution execution;
123:           private Exception exception;
124:           private T result;
125: 
126:           public BlockingOperation(Execution execution) {
127:             this.execution = execution;
128:           }
129: 
130:           @Override
131:           public T call() throws Exception {
132:             execution.intercept(ExecInterceptor.ExecType.BLOCKING, execution.interceptors, new Action<Execution>() {
133:               @Override
134:               public void execute(Execution execution) throws Exception {
135:                 try {
136:                   result = blockingOperation.call();
137:                 } catch (Exception e) {
138:                   exception = e;
139:                 }
140:               }
141:             });
142: 
143:             if (exception != null) {
144:               throw exception;
145:             } else {
146:               return result;
147:             }
148:           }
149:         }
150: 
151:         class ComputeResume implements FutureCallback<T> {
152:           private final Fulfiller<? super T> fulfiller;
153: 
154:           public ComputeResume(Fulfiller<? super T> fulfiller) {
155:             this.fulfiller = fulfiller;
156:           }
157: 
158:           @Override
159:           public void onSuccess(final T result) {
160:             fulfiller.success(result);
161:           }
162: 
163:           @SuppressWarnings("NullableProblems")
164:           @Override
165:           public void onFailure(final Throwable t) {
166:             fulfiller.error(t);
167:           }
168:         }
169:       });
170: 
171:     }
172: 
173:     @Override
174:     public <T> Promise<T> promise(Action<? super Fulfiller<T>> action) {
175:       return new DefaultPromise<>(executionFactory, action);
176:     }
177: 
178:     @Override
179:     public void fork(Action<? super ratpack.exec.Execution> action) {
180:       start(action);
181:     }
182: 
183:     @Override
184:     public <T> void stream(Publisher<T> publisher, final Subscriber<T> subscriber) {
185:       publisher.subscribe(new Subscriber<T>() {
186:         final Execution execution = getExecution();
187: 
188:         @Override
189:         public void onSubscribe(final Subscription subscription) {
190:           this.execution.continueVia(new Runnable() {
191:             @Override
192:             public void run() {
193:               subscriber.onSubscribe(subscription);
194:             }
195:           });
196:         }
197: 
198:         @Override
199:         public void onNext(final T element) {
200:           this.execution.continueExecutionAndWait(new Action<ratpack.exec.Execution>() {
201:             @Override
202:             public void execute(ratpack.exec.Execution execution) throws Exception {
203:               subscriber.onNext(element);
204:             }
205:           });
206:         }
207: 
208:         @Override
209:         public void onComplete() {
210:           this.execution.joinExecutionEnd(new Action<ratpack.exec.Execution>() {
211:             @Override
212:             public void execute(ratpack.exec.Execution execution) throws Exception {
213:               subscriber.onComplete();
214:             }
215:           });
216:         }
217: 
218:         @Override
219:         public void onError(final Throwable cause) {
220:           this.execution.joinExecutionEnd(new Action<ratpack.exec.Execution>() {
221:             @Override
222:             public void execute(ratpack.exec.Execution execution) throws Exception {
223:               subscriber.onError(cause);
224:             }
225:           });
226:         }
227:       });
228:     }
229:   }
