30: /**
31:  * An extension module that provides support for Thymeleaf templating engine.
32:  * <p>
33:  * To use it one has to register the module and then render {@link ratpack.thymeleaf.Template} instances.
34:  * Instances of {@code Template} can be created using one of the
35:  * {@link ratpack.thymeleaf.Template#thymeleafTemplate(java.util.Map, String, String)}
36:  * static methods.
37:  * </p>
38:  * <p>
39:  * By default templates are looked up in the {@code thymeleaf} directory of the application root with a {@code .html} suffix.
40:  * So {@code thymeleafTemplate("my/template/path")} maps to {@code thymeleaf/my/template/path.html} in the application root directory.
41:  * This can be configured using {@link #setTemplatesPrefix(String)} and {@link #setTemplatesSuffix(String)} as well as
42:  * {@code other.thymeleaf.templatesPrefix} and {@code other.thymeleaf.templatesSuffix} configuration properties.
43:  * </p>
44:  * <p>
45:  * Response content type can be manually specified, i.e. {@code thymeleafTemplate("template", model, "text/html")} if
46:  * not specified will default to {@code text/html}.
47:  * </p>
48:  *
49:  * Example usage: (Java DSL)
50:  * <pre class="tested">
51:  * import ratpack.handling.*;
52:  * import ratpack.guice.*;
53:  * import ratpack.util.*;
54:  * import ratpack.launch.*;
55:  * import ratpack.thymeleaf.ThymeleafModule;
56:  * import static ratpack.thymeleaf.Template.thymeleafTemplate;
57:  *
58:  * class MyHandler implements Handler {
59:  *   void handle(final Context context) {
60:  *     context.render(thymeleafTemplate("my/template/path", key: "it works!"));
61:  *   }
62:  * }
63:  *
64:  * class ModuleBootstrap implements Action&lt;ModuleRegistry&gt; {
65:  *   public void execute(ModuleRegistry modules) {
66:  *     modules.register(new ThymeleafModule());
67:  *   }
68:  * }
69:  *
70:  * LaunchConfig launchConfig = LaunchConfigBuilder.baseDir(new File("appRoot"))
71:  *     .build(new HandlerFactory() {
72:  *   public Handler create(LaunchConfig launchConfig) {
73:  *     return Guice.handler(launchConfig, new ModuleBootstrap(), new Action&lt;Chain&gt;() {
74:  *       public void execute(Chain chain) {
75:  *         chain.handler(chain.getRegistry().get(MyHandler.class));
76:  *       }
77:  *     });
78:  *   }
79:  * });
80:  * </pre>
81:  *
82:  * Example usage: (Groovy DSL)
83:  * <pre class="groovy-ratpack-dsl">
84:  * import ratpack.thymeleaf.ThymeleafModule
85:  * import static ratpack.thymeleaf.Template.thymeleafTemplate
86:  *
87:  * ratpack {
88:  *   modules {
89:  *     register new ThymeleafModule()
90:  *   }
91:  *   handlers {
92:  *     get {
93:  *       render thymeleafTemplate('my/template/path', key: 'it works!')
94:  *     }
95:  *   }
96:  * }
97:  * </pre>
98:  *
99:  * @see <a href="http://www.thymeleaf.org/" target="_blank">Thymeleaf</a>
100:  */
101: public class ThymeleafModule extends AbstractModule {
102: 
103:   private static final String DEFAULT_TEMPLATE_MODE = "XHTML";
104:   private static final String DEFAULT_TEMPLATE_PREFIX = "thymeleaf";
105:   private static final String DEFAULT_TEMPLATE_SUFFIX = ".html";
106: 
107:   private String templatesMode;
108:   private String templatesPrefix;
109:   private String templatesSuffix;
110:   private Boolean templatesCacheSize;
111:   private Long cacheTTLMs;
112: 
113:   public String getTemplatesMode() {
114:     return templatesMode;
115:   }
116: 
117:   public void setTemplatesMode(String templatesMode) {
118:     this.templatesMode = templatesMode;
119:   }
120: 
121:   public String getTemplatesPrefix() {
122:     return templatesPrefix;
123:   }
124: 
125:   public void setTemplatesPrefix(String templatesPrefix) {
126:     this.templatesPrefix = templatesPrefix;
127:   }
128: 
129:   public String getTemplatesSuffix() {
130:     return templatesSuffix;
131:   }
132: 
133:   public void setTemplatesSuffix(String templatesSuffix) {
134:     this.templatesSuffix = templatesSuffix;
135:   }
136: 
137:   public Boolean isTemplatesCacheable() {
138:     return templatesCacheSize;
139:   }
140: 
141:   public void setTemplatesCacheable(Boolean templatesCacheable) {
142:     this.templatesCacheSize = templatesCacheable;
143:   }
144: 
145:   public Long getCacheTTLMs() {
146:     return cacheTTLMs;
147:   }
148: 
149:   public void setCacheTTLMs(Long cacheTTLMs) {
150:     this.cacheTTLMs = cacheTTLMs;
151:   }
152: 
153:   @Override
154:   protected void configure() {
155:     bind(ThymeleafTemplateRenderer.class).in(Singleton.class);
156:     bind(ITemplateResolver.class).to(FileTemplateResolver.class).in(Singleton.class);
157:   }
158: 
159:   @SuppressWarnings("UnusedDeclaration")
160:   @Provides
161:   FileTemplateResolver provideITemplateResolver(LaunchConfig launchConfig) {
162:     final FileTemplateResolver templateResolver = new FileTemplateResolver();
163: 
164:     String mode = templatesMode == null ? launchConfig.getOther("thymeleaf.templatesMode", DEFAULT_TEMPLATE_MODE) : templatesMode;
165:     String prefix = templatesPrefix == null ? launchConfig.getOther("thymeleaf.templatesPrefix", DEFAULT_TEMPLATE_PREFIX) : templatesPrefix;
166:     String suffix = templatesSuffix == null ? launchConfig.getOther("thymeleaf.templatesSuffix", DEFAULT_TEMPLATE_SUFFIX) : templatesSuffix;
167:     Boolean cacheable = templatesCacheSize == null ? Boolean.valueOf(launchConfig.getOther("thymeleaf.templatesCacheable", "true")) : templatesCacheSize;
168:     Long cacheTTL = cacheTTLMs == null ? Long.valueOf(launchConfig.getOther("thymeleaf.cacheTTLMs", "0")) : cacheTTLMs;
169: 
170:     templateResolver.setTemplateMode(mode);
171: 
172:     File finalPrefixPathFile = new File(launchConfig.getBaseDir(), prefix);
173:     String path = finalPrefixPathFile.getAbsolutePath();
174:     if (path.charAt(path.length() - 1) != File.separatorChar) {
175:       path += File.separator;
176:     }
177:     templateResolver.setPrefix(path);
178: 
179:     if (suffix.equalsIgnoreCase("")) {
180:       suffix = DEFAULT_TEMPLATE_SUFFIX;
181:     }
182:     templateResolver.setSuffix(suffix);
183: 
184:     templateResolver.setCacheable(cacheable != null && cacheable);
185:     templateResolver.setCacheTTLMs(cacheTTL != null && cacheTTL > 0 ? cacheTTL : null);
186: 
187:     return templateResolver;
188:   }
189: 
190:   @SuppressWarnings("UnusedDeclaration")
191:   @Provides
192:   @Singleton
193:   TemplateEngine provideTemplateEngine(ITemplateResolver templateResolver) {
194:     final TemplateEngine templateEngine = new TemplateEngine();
195:     templateEngine.setTemplateResolver(templateResolver);
196:     return templateEngine;
197:   }
198: }

