31: public class DefaultRxBackground implements RxBackground {
32: 
33:   private final Provider<Background> background;
34: 
35:   @Inject
36:   public DefaultRxBackground(Provider<Background> backgroundProvider) {
37:     this.background = backgroundProvider;
38:   }
39: 
40:   @Override
41:   public <T> Observable<T> observe(final Callable<T> callable) {
42:     return Observable.create(new Observable.OnSubscribeFunc<T>() {
43:       @Override
44:       public Subscription onSubscribe(final Observer<? super T> observer) {
45:         background.get().exec(callable).onError(new Action<Throwable>() {
46:           @Override
47:           public void execute(Throwable thing) throws Exception {
48:             observer.onError(thing);
49:           }
50:         }).then(new Action<T>() {
51:           @Override
52:           public void execute(T thing) throws Exception {
53:             observer.onNext(thing);
54:             observer.onCompleted();
55:           }
56:         });
57:         return Subscriptions.empty();
58:       }
59:     });
60:   }
61: 
62:   @Override
63:   public <I extends Iterable<T>, T> Observable<T> observeEach(final Callable<I> callable) {
64:     return Observable.create(new Observable.OnSubscribeFunc<T>() {
65:       @Override
66:       public Subscription onSubscribe(final Observer<? super T> observer) {
67:         background.get().exec(callable).onError(new Action<Throwable>() {
68:           @Override
69:           public void execute(Throwable thing) throws Exception {
70:             observer.onError(thing);
71:           }
72:         }).then(new Action<I>() {
73:           @Override
74:           public void execute(I things) throws Exception {
75:             for (T thing : things) {
76:               observer.onNext(thing);
77:             }
78: 
79:             observer.onCompleted();
80:           }
81:         });
82:         return Subscriptions.empty();
83:       }
84:     });
85:   }
